const express = require("express");const router = express.Router();function safeRequire(path, routeName) {  try {    return require(path);  } catch (error) {    console.warn(`[ROUTES] ${routeName} route not loaded: ${error.message}`);    return null;  }}const healthRoutes = safeRequire("./health.routes", "health");const blockchainRoutes = safeRequire("./blockchain.routes", "blockchain");const fabricRoutes = safeRequire("./fabric.routes", "fabric");const walletRoutes = safeRequire("./wallet.routes", "wallet");if (healthRoutes) {  router.use("/health", healthRoutes);}if (blockchainRoutes) {  router.use("/blockchain", blockchainRoutes);}if (fabricRoutes) {  router.use("/fabric", fabricRoutes);}if (walletRoutes) {  router.use("/wallets", walletRoutes);}router.get("/", (req, res) => {  return res.status(200).json({    success: true,    message: "Blockchain API v1 is running",    data: {      availableRoutes: {        health: "/api/v1/health",        blockchainStatus: "/api/v1/blockchain/status",        fabricSubmit: "/api/v1/fabric/submit",        walletCreation: "/api/v1/wallets"      }    },    meta: null,    timestamp: new Date().toISOString()  });});module.exports = router;
