10. Insert BANK001 Organization
Create:
nano insert-bank001-organization.sql
Paste:
BEGIN;DO $$DECLARE    v_schema_name TEXT := 'blockchain';    v_table_name  TEXT := 'organizations';    v_org_id UUID := gen_random_uuid();    v_columns TEXT[];    v_id_column TEXT;    v_code_column TEXT;    v_name_column TEXT;    v_insert_columns TEXT := '';    v_insert_values  TEXT := '';    v_exists_sql TEXT;    v_exists BOOLEAN := FALSE;    v_sql TEXT;BEGIN    SELECT array_agg(column_name::TEXT ORDER BY ordinal_position)    INTO v_columns    FROM information_schema.columns    WHERE table_schema = v_schema_name      AND table_name = v_table_name      AND is_generated = 'NEVER';    IF v_columns IS NULL THEN        RAISE EXCEPTION 'Table %.% does not exist', v_schema_name, v_table_name;    END IF;    IF 'organization_id' = ANY(v_columns) THEN        v_id_column := 'organization_id';    ELSIF 'id' = ANY(v_columns) THEN        v_id_column := 'id';    ELSIF 'org_id' = ANY(v_columns) THEN        v_id_column := 'org_id';    ELSE        v_id_column := NULL;    END IF;    IF 'organization_code' = ANY(v_columns) THEN        v_code_column := 'organization_code';    ELSIF 'org_code' = ANY(v_columns) THEN        v_code_column := 'org_code';    ELSIF 'code' = ANY(v_columns) THEN        v_code_column := 'code';    ELSIF 'bank_code' = ANY(v_columns) THEN        v_code_column := 'bank_code';    ELSIF 'external_org_id' = ANY(v_columns) THEN        v_code_column := 'external_org_id';    ELSE        v_code_column := NULL;    END IF;    IF 'organization_name' = ANY(v_columns) THEN        v_name_column := 'organization_name';    ELSIF 'org_name' = ANY(v_columns) THEN        v_name_column := 'org_name';    ELSIF 'name' = ANY(v_columns) THEN        v_name_column := 'name';    ELSIF 'bank_name' = ANY(v_columns) THEN        v_name_column := 'bank_name';    ELSE        v_name_column := NULL;    END IF;    RAISE NOTICE 'Detected id column: %', v_id_column;    RAISE NOTICE 'Detected code column: %', v_code_column;    RAISE NOTICE 'Detected name column: %', v_name_column;    IF v_code_column IS NOT NULL THEN        v_exists_sql := format(            'SELECT EXISTS (SELECT 1 FROM %I.%I WHERE %I = $1)',            v_schema_name,            v_table_name,            v_code_column        );        EXECUTE v_exists_sql INTO v_exists USING 'BANK001';        IF v_exists THEN            RAISE NOTICE 'BANK001 already exists in %.%. Skipping insert.', v_schema_name, v_table_name;            RETURN;        END IF;    END IF;    IF v_id_column IS NOT NULL THEN        v_insert_columns := v_insert_columns || format('%I, ', v_id_column);        v_insert_values  := v_insert_values  || quote_literal(v_org_id) || '::uuid, ';    END IF;    IF v_code_column IS NOT NULL THEN        v_insert_columns := v_insert_columns || format('%I, ', v_code_column);        v_insert_values  := v_insert_values  || quote_literal('BANK001') || ', ';    END IF;    IF v_name_column IS NOT NULL THEN        v_insert_columns := v_insert_columns || format('%I, ', v_name_column);        v_insert_values  := v_insert_values  || quote_literal('Bank 001') || ', ';    END IF;    IF 'organization_type' = ANY(v_columns) THEN        v_insert_columns := v_insert_columns || 'organization_type, ';        v_insert_values  := v_insert_values  || quote_literal('BANK') || ', ';    END IF;    IF 'org_type' = ANY(v_columns) THEN        v_insert_columns := v_insert_columns || 'org_type, ';        v_insert_values  := v_insert_values  || quote_literal('BANK') || ', ';    END IF;    IF 'type' = ANY(v_columns) THEN        v_insert_columns := v_insert_columns || 'type, ';        v_insert_values  := v_insert_values  || quote_literal('BANK') || ', ';    END IF;    IF 'status' = ANY(v_columns) THEN        v_insert_columns := v_insert_columns || 'status, ';        v_insert_values  := v_insert_values  || quote_literal('ACTIVE') || ', ';    END IF;    IF 'organization_status' = ANY(v_columns) THEN        v_insert_columns := v_insert_columns || 'organization_status, ';        v_insert_values  := v_insert_values  || quote_literal('